    about_peter_bio: 'Peter no le teme a las ideas arriesgadas. Escucha, pregunta y actúa de inmediato ante cualquier comentario sobre Gavelling. No es solo una figura con buenas ideas, sino alguien que ha entrenado activamente a su propia delegación para ganar más de 100 premios en un solo año. En definitiva, la diversión, la aventura y la creatividad no tienen límites para Peter, habiendo viajado a más de 40 países a los 22 años.',
